      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": ["Peter W. Shor", "Alexei Kitaev", "Andrew M. Steane"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction made reliable quantum information processing physically plausible and reshaped quantum information physics. Its foundational importance and broad influence merit serious consideration.",
        "attribution": "Shor and Steane established seminal codes; Kitaev developed the topological-code framework. These are distinct, central contributions, though the field's development is broader.",
        "maturity": "The ideas have been tested across many platforms, with ongoing experimental progress toward fault-tolerant operation. The intellectual contribution is mature even as practical systems continue to develop.",
        "uncertainties": ["The boundary between the foundational discoveries and later advances enabling fault tolerance is difficult to draw."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B011",
      "proposed_laureates": ["Charles L. Bennett", "David N. Spergel", "Lyman A. Page Jr."],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of the cosmic microwave background established a quantitative foundation for modern cosmology and determined key properties of the universe.",
        "attribution": "Bennett led the mission and its instrument effort; Page and Spergel made major experimental and interpretive contributions. The result depended on a large team, so individual credit needs careful boundaries.",
        "maturity": "The maps and cosmological conclusions have been tested against later observations, including Planck and large-scale-structure measurements.",
        "uncertainties": ["The extent to which the prize should recognize WMAP specifically versus the wider progression of CMB precision cosmology is debatable."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B028",
      "proposed_laureates": ["Sheperd S. Doeleman", "Heino Falcke", "James M. Moran"],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging brought black-hole-scale structure into direct observation and demonstrated the power of global very-long-baseline interferometry at extreme angular resolution.",
        "attribution": "Doeleman led the observational effort, Falcke helped establish the case and interpretation for imaging a black-hole shadow, and Moran contributed foundational interferometric expertise. The collaboration's scale complicates individual attribution.",
        "maturity": "Images of M87* and Sagittarius A* provide important repetition across two sources, although image reconstruction and interpretation depend on complex analysis.",
        "uncertainties": ["The Nobel-sized discovery may be framed as the images, the observing technique, or the underlying black-hole tests; those frames imply different credit."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B025",
      "proposed_laureates": ["Claudio Pellegrini", "Jörg Rossbach", "Kwang-Je Kim"],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers opened an intense, ultrafast X-ray regime that enables measurements of matter and dynamics inaccessible to conventional sources.",
        "attribution": "Pellegrini, Rossbach, and Kim made major conceptual and accelerator-physics contributions to the development of the technology. Facilities and later advances involved many additional contributors.",
        "maturity": "Operating facilities have produced a sustained body of science, demonstrating that this is a durable research tool rather than a single-purpose proposal.",
        "uncertainties": ["The credit boundary between the key accelerator concepts, first successful facility, and subsequent technical development is not simple."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B034",
      "proposed_laureates": ["Francis Halzen", "Albrecht Karle"],
      "assessment": {
        "nobel_worthiness": "High-energy astrophysical neutrinos established a new messenger for studying the nonthermal universe and connected particle detection in ice to distant cosmic accelerators.",
        "attribution": "Halzen was a leading advocate and scientific architect of IceCube; Karle led major detector and collaboration work. The discovery is inseparable from a large instrument team.",
        "maturity": "The astrophysical flux is established, with continuing source-identification work and accumulating observations.",
        "uncertainties": ["The specific sources and emission mechanisms remain incompletely identified, and individual credit for a large collaboration discovery is difficult."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B021",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exceptional precision with the prospect of practical comparisons between clocks, enabling tests of fundamental physics and new measurement applications.",
        "attribution": "Katori introduced the lattice-clock approach and Ye made major advances in precision and performance. Their complementary contributions are plausible individual recognitions.",
        "maturity": "The clocks have undergone extensive refinement and independent comparison, though their full metrological and scientific impact continues to grow.",
        "uncertainties": ["The strongest case may depend on whether the central achievement is the original clock concept or the later realization of unprecedented accuracy and stability."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": ["Charles L. Kane", "Eugene J. Mele", "Laurens W. Molenkamp"],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator phases revealed robust electronic states governed by topology, opening a major direction in condensed-matter physics.",
        "attribution": "Kane and Mele developed the foundational theory; Molenkamp's experiments provided an early decisive demonstration. The proposed trio spans theory and experiment.",
        "maturity": "The original effects are well established, although many predicted materials and device applications have proved more complicated than early expectations.",
        "uncertainties": ["The discovery is closely related to broader work on topological phases, and the strongest division of credit across theory and experiment requires expert review."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B004",
      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Optical lattices made highly controlled quantum simulation of interacting many-body systems possible and enabled landmark studies of quantum phases.",
        "attribution": "Bloch and Greiner established influential experimental demonstrations; Zoller helped develop the theoretical framework for using ultracold atoms as quantum simulators.",
        "maturity": "The platform has produced a substantial and reproducible research program, though its status as a distinct Nobel-sized discovery is less settled than its scientific value.",
        "uncertainties": ["The contribution is a sustained platform development involving many groups, and its most consequential physics results may still be emerging."]
      }
    }
  ]
